extern bf_status_t bf_map_logical_umac3_to_physical(bf_dev_id_t dev_id,
                                                    uint32_t logical_umac,
                                                    uint32_t *physical_umac);
/*******************************************************************
*  access  : read-write
*  block   : interrupts0
*  register: setintenable0
*  field   : setinten0
*----------:
*  dev_id  : logical chip identifier
*  umac    : logical UMAC3 identifier (0-65 (tof1), 0/39 (tof2))
*  reg32   : u32 for resulting register value or contents to extract field from
*  fld32   : u32 for field inserted or extracted
*  hw      : true=read/write hw : false=insert/extract from reg32 (only)
*----------+
*
* Fifoctrl Ch#0 RX sync Interrupt set. When a 1 is writen to the this
* bit the corresponding interrupt is enabled; when a zero is written to
* this bit there is no change in the interrupt enable state. Reading
* either the 'set' or 'clr' address for this register returns the
* current state on the interrupt enable.
* 
*******************************************************************/
bf_status_t bf_ll_umac3_interrupts0__setintenable0__setinten0_rd(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t *fld32, bool hw) {
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_interrupts0__setintenable0__setinten0_rd(dev_id, physical_umac, reg32, fld32, hw);
  return BF_SUCCESS;
}

bf_status_t bf_ll_umac3_interrupts0__setintenable0__setinten0_wr(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t  fld32, bool hw) {
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_interrupts0__setintenable0__setinten0_wr(dev_id, physical_umac, reg32, fld32, hw);
  return BF_SUCCESS;
}

bf_status_t bf_ll_umac3_interrupts0__setintenable0__setinten0_rmw(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t  fld32) {
  uint32_t unused_fld32;
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_interrupts0__setintenable0__setinten0_rd(dev_id, physical_umac, reg32, &unused_fld32, true);
  umac3_interrupts0__setintenable0__setinten0_wr(dev_id, physical_umac, reg32, fld32, true);
  return BF_SUCCESS;
}


