/*******************************************************************
*  access  : read-write
*  block   : stats0
*  register: rdctrl
*  field   : rsc
*----------:
*  dev_id  : logical chip identifier
*  umac    : logical UMAC3 identifier (0-65 (tof1), 0/39 (tof2))
*  reg32   : u32 for resulting register value or contents to extract field from
*  fld32   : u32 for field inserted or extracted
*  hw      : true=read/write hw : false=insert/extract from reg32 (only)
*----------+
*
* This is set by Software for the UMAC to read a statistics counter.
* When this bit is set, the UMAC accesses internal memory and reads the
* specified counter. Once the read operation completes, the bit is
* cleared by the UMAC. The following are the steps for reading the
* Statistics Counter. 1) Read and Verify this bit is cleared. If not
* cleared wait until the bit is cleared (polling) 2) Program the Counter
* to access and set this bit to 1'b1. 3) Poll this register until the
* bit is cleared. 4) The counter information is available in the X-UMAC
* Statistics Read Data Registers.
* 
*******************************************************************/
bf_status_t bf_ll_umac3_stats0__rdctrl__rsc_rd(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t *fld32, bool hw) {
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_stats0__rdctrl__rsc_rd(dev_id, physical_umac, reg32, fld32, hw);
  return BF_SUCCESS;
}

bf_status_t bf_ll_umac3_stats0__rdctrl__rsc_wr(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t  fld32, bool hw) {
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_stats0__rdctrl__rsc_wr(dev_id, physical_umac, reg32, fld32, hw);
  return BF_SUCCESS;
}

bf_status_t bf_ll_umac3_stats0__rdctrl__rsc_rmw(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t  fld32) {
  uint32_t unused_fld32;
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_stats0__rdctrl__rsc_rd(dev_id, physical_umac, reg32, &unused_fld32, true);
  umac3_stats0__rdctrl__rsc_wr(dev_id, physical_umac, reg32, fld32, true);
  return BF_SUCCESS;
}


