/*******************************************************************
*  access  : read-write
*  block   : fifoctrl0
*  register: txfifoctrl0
*  field   : txthreshold0
*----------:
*  dev_id  : logical chip identifier
*  umac    : logical UMAC3 identifier (0-65 (tof1), 0/39 (tof2))
*  reg32   : u32 for resulting register value or contents to extract field from
*  fld32   : u32 for field inserted or extracted
*  hw      : true=read/write hw : false=insert/extract from reg32 (only)
*----------+
*
* The field indicates the threshold which is used by APP_FIFO before
* reading out the data from TX_FIFO and sending it to MAC. When the FIFO
* Fill level is equal to or greater than the Threshold value or EOF is
* seen, then the FIFO is read out and sent to MAC.  To Avoid deadlock,
* this value should never be greater than the (FIFO_DEPTH-
* SEL_AFULLTHRESH-N_ADDITIONAL_TXVALIDS).  Here, FIFO_DEPTH = Depth of
* the FIFO associated with Ch#0, SEL_AFULLTHRES = Selected Almost Full
* Threshold for Ch#0 and N_ADDITIONAL_TXVALIDS = Number of Additional
* Valids that APP Logic generates after the assertion of TxAfull on
* Ch#0.
* 
*******************************************************************/
bf_status_t bf_ll_umac3_fifoctrl0__txfifoctrl0__txthreshold0_rd(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t *fld32, bool hw) {
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_fifoctrl0__txfifoctrl0__txthreshold0_rd(dev_id, physical_umac, reg32, fld32, hw);
  return BF_SUCCESS;
}

bf_status_t bf_ll_umac3_fifoctrl0__txfifoctrl0__txthreshold0_wr(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t  fld32, bool hw) {
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_fifoctrl0__txfifoctrl0__txthreshold0_wr(dev_id, physical_umac, reg32, fld32, hw);
  return BF_SUCCESS;
}

bf_status_t bf_ll_umac3_fifoctrl0__txfifoctrl0__txthreshold0_rmw(bf_dev_id_t dev_id, uint32_t logical_umac, uint32_t *reg32, uint32_t  fld32) {
  uint32_t unused_fld32;
  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_fifoctrl0__txfifoctrl0__txthreshold0_rd(dev_id, physical_umac, reg32, &unused_fld32, true);
  umac3_fifoctrl0__txfifoctrl0__txthreshold0_wr(dev_id, physical_umac, reg32, fld32, true);
  return BF_SUCCESS;
}


