  uint32_t physical_umac;
  bf_status_t rc = bf_map_logical_umac3_to_physical(dev_id, logical_umac, &physical_umac);

  if (rc != BF_SUCCESS) return rc;

  umac3_fecrs0__ieeecfg__blrobust_wr(dev_id, physical_umac, channel, reg32, fld32, hw);
